type Row = Outputs["playlists"]["list"]["data"][number];
type Detail = Outputs["playlists"]["get"];
type Input<K extends keyof Inputs["playlists"]> = Inputs["playlists"][K];

const PAGE_SIZE = 20;
const KEY = ["playlists"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.owner_id === user.id;
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.owner_id === user.id;
}

/** Filters this page always applies */
function fixedFilter(user: SessionUser | null) {
  void user;
  return { owner_id: user?.id ?? "" };
}

/** Who may open this page */
function canOpen(user: SessionUser | null): boolean {
  return user !== null;
}

function AccessGate({ user }: { user: SessionUser | null }) {
  return (
    <div className="mx-auto max-w-md p-6">
      <Card>
        <CardHeader>
          <CardTitle>{user ? "No access" : "Sign in required"}</CardTitle>
          <CardDescription>{user ? "Your account cannot open this page." : "Sign in to open this page."}</CardDescription>
        </CardHeader>
        {user ? null : (
          <CardContent>
            <Link href="/login" className={buttonVariants()}>
              Sign in
            </Link>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

/** Waits for the session, then renders the page or the gate */
function guarded<P extends object>(Component: (props: P) => ReactNode) {
  return function Guarded(props: P) {
    const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
    if (session.isPending) return <PaneSkeleton />;
    const user = sessionUser(session.data);
    if (!canOpen(user)) return <AccessGate user={user} />;
    return <Component {...props} />;
  };
}

const PLAYLISTS_FIELDS = ["name", "public"] as const;
type PlaylistsField = (typeof PLAYLISTS_FIELDS)[number];

type PlaylistsValues = {
  name: string;
  public: boolean;
};

const EMPTY_PLAYLISTS: PlaylistsValues = {
  name: "",
  public: false
};

const PLAYLISTS_CREATE: readonly PlaylistsField[] = ["name", "public"];

function toPlaylistsCreateInput(v: PlaylistsValues): Input<"create"> {
  return {
    name: v.name,
    public: v.public
  };
}

const PLAYLISTS_UPDATE: readonly PlaylistsField[] = ["name", "public"];

function toPlaylistsUpdateInput(v: PlaylistsValues): Input<"update">["data"] {
  return {
    name: v.name,
    public: v.public
  };
}

function playlistsFromRow(row: Detail): PlaylistsValues {
  return {
    name: text(row.name),
    public: row.public ?? false
  };
}

type PlaylistsSetter = <K extends keyof PlaylistsValues>(key: K, value: PlaylistsValues[K]) => void;

function renderPlaylistsField(field: PlaylistsField, values: PlaylistsValues, set: PlaylistsSetter) {
  switch (field) {
    case "name":
      return (
      <FormRow label="Name" htmlFor="name">
        <Input id="name" type="text" maxLength={120} value={values.name} onChange={e => set("name", e.target.value)} required />
      </FormRow>
      );
    case "public":
      return (
      <div className="flex items-center gap-2">
        <Checkbox id="public" checked={values.public} onCheckedChange={checked => set("public", checked)} />
        <Label htmlFor="public">Public</Label>
      </div>
      );
  }
}

function PlaylistsForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly PlaylistsField[];
  initial: PlaylistsValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: PlaylistsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<PlaylistsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: PlaylistsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderPlaylistsField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function PlaylistsLayoutInner({ children }: { children: ReactNode }) {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE, ...fixedFilter(user) } as Inputs["playlists"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.playlists.list(input), enabled: user !== null });
  const pathname = usePathname();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Playlists" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/playlists/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New playlist">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No playlists yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    href={`/playlists/${text(row.id)}`}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", pathname === `/playlists/${text(row.id)}` && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.name) || "Playlist " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[(row.public ? "Public" : "Not public")].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        {children}
      </section>
    </div>
  );
}

function PlaylistsIndexInner() {
  return <EmptyPane>Select a playlist from the list, or create one.</EmptyPane>;
}

function PlaylistsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.playlists.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/playlists/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New playlist">
      <PlaylistsForm
        fields={PLAYLISTS_CREATE}
        initial={EMPTY_PLAYLISTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toPlaylistsCreateInput(values))}
      />
    </Pane>
  );
}

/**
 * The tracks of a playlist: the Track rows PlaylistTrack links it to, in the order of its position. Changes go
 * through playlist_tracks, under its own rules; the names come with the row.
 */
function PlaylistsTracksField({ row, user }: { row: Detail; user: SessionUser | null }) {
  void user;
  const queryClient = useQueryClient();
  const linkInput = { playlist_id: row.id, page_size: 200 } as Inputs["playlist_tracks"]["list"];
  const links = useQuery({ queryKey: ["playlist_tracks", "list", linkInput], queryFn: () => client.playlist_tracks.list(linkInput) });
  const options = useQuery({ queryKey: ["tracks", "list", { page_size: 200 }], queryFn: () => client.tracks.list({ page_size: 200 }) });
  const settle = async () => {
    await queryClient.invalidateQueries({ queryKey: ["playlist_tracks"] });
    await queryClient.invalidateQueries({ queryKey: KEY });
  };
  void settle;
  const add = useMutation({ mutationFn: (input: Inputs["playlist_tracks"]["create"]) => client.playlist_tracks.create(input), onSuccess: settle });
  const remove = useMutation({ mutationFn: (input: Inputs["playlist_tracks"]["delete"]) => client.playlist_tracks.delete(input), onSuccess: settle });
  const move = useMutation({ mutationFn: (input: Inputs["playlist_tracks"]["move"]) => client.playlist_tracks.move(input), onSuccess: settle });
  type Link = Outputs["playlist_tracks"]["list"]["data"][number];
  const far = new Map(row.tracks.map(item => [text(item.id), item] as const));
  const label = (link: Link) => text(far.get(text(link.track_id))?.title);
  const items = [...(links.data?.data ?? [])].sort((a, b) => Number(a.position) - Number(b.position));
  const busy = add.isPending || remove.isPending || move.isPending;
  return (
    <div>
      {links.data ? <OrderedList items={items} keyOf={link => text(link.id)} label={label} onMove={user !== null && row.owner_id === user.id ? (link, to) => move.mutate({ id: link.id, to }) : undefined} onRemove={user !== null && row.owner_id === user.id ? link => remove.mutate({ id: link.id }) : undefined} busy={busy} /> : <OrderedList items={row.tracks} keyOf={item => text(item.id) + ":" + row.tracks.indexOf(item)} label={item => text(item.title)} />}
      {user !== null && row.owner_id === user.id ? (
        <AddPicker
          options={(options.data?.data ?? [])}
          keyOf={item => text(item.id)}
          label={item => text(item.title)}
          placeholder="Add a track…"
          onAdd={item => add.mutate({ playlist_id: row.id, track_id: item.id } as Inputs["playlist_tracks"]["create"])}
          busy={busy}
        />
      ) : null}
      <ErrorNote error={add.error ?? remove.error ?? move.error} className="mt-2" />
    </div>
  );
}

function PlaylistsDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.playlists.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["playlists"]["update"]) => client.playlists.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["playlists"]["delete"]) => client.playlists.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/playlists");
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Playlist " + text(row.id)}
      actions={
        <>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this playlist?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <PlaylistsForm
          fields={PLAYLISTS_UPDATE}
          initial={playlistsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toPlaylistsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Owner">{text(row.owner_id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Public">{row.public == null ? "—" : <Badge variant={row.public ? "default" : "outline"}>{yesNo(row.public)}</Badge>}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Tracks">
          <PlaylistsTracksField row={row} user={user} />
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const PlaylistsLayout = guarded(PlaylistsLayoutInner);
export const PlaylistsIndex = guarded(PlaylistsIndexInner);
export const PlaylistsNew = guarded(PlaylistsNewInner);
export const PlaylistsDetail = guarded(PlaylistsDetailInner);
